Quantum GetPixelChannel(const Image *image, const PixelChannel channel, const Quantum *pixel) {
    if (image == (const Image *) NULL || pixel == (const Quantum *) NULL) {
        return 0;
    }

    if (channel >= LastPixelChannel || (image->channel_mask & (1ULL << channel)) == 0) {
        return 0;
    }

    return pixel[channel];
}

Quantum GetPixelChannel(const Image *image, const PixelChannel channel, const Quantum *pixel) {
    if (image->channel_mask & (1ULL << channel)) {
        return pixel[channel];
    }
    return 0;
}

Quantum GetPixelChannel(const Image *image, const PixelChannel channel, const Quantum *pixel) {
    if (image->channel_info[channel].traits == UndefinedPixelChannel) {
        return 0;
    }
    return pixel[channel];
}

Quantum GetPixelChannel(const Image *image, const PixelChannel channel, const Quantum *pixel) {
    if (channel >= LastPixelChannel)
        return 0;

    return pixel[channel];
}

Quantum GetPixelChannel(const Image *image, const PixelChannel channel, const Quantum *pixel) {
    if (image->channel_traits[channel] == UndefinedPixelChannel)
        return 0;

    return pixel[channel];
}
